async () => {
const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const trig = [...document.querySelectorAll('button')].find((b) => txt(b.innerText) === 'Handle Color' && b.hasAttribute('aria-expanded'));
if (!trig) return { err: 'NO TRIGGER Handle Color' };
if (trig.getAttribute('aria-expanded') !== 'true') { trig.scrollIntoView({ block: 'center' }); trig.click(); await wait(800); }
const panel = document.getElementById(trig.getAttribute('aria-controls') || '');
if (!panel) return { err: 'NO PANEL' };
const link = [...panel.querySelectorAll('a')].find((a) => txt(a.innerText) === 'View in full mode');
if (!link) return { err: 'NO FULL MODE LINK' };
link.click(); await wait(1500);
const dialog = document.querySelector('[role=dialog][aria-label="Handle Color"]');
if (!dialog) return { err: 'NO DIALOG' };
const names = () => [...dialog.querySelectorAll('button[class*=selectButton]')].map((b) => txt(b.getAttribute('aria-label'))).sort();
const before = names();
const btn = [...dialog.querySelectorAll('button[aria-haspopup=listbox]')].find((b) => txt(b.innerText) === 'Price');
if (!btn) return { err: 'NO PRICE BUTTON', before: before.length };
btn.click(); await wait(600);
const lb = [...document.querySelectorAll('[role=listbox][aria-label=Price]')].pop();
if (!lb) return { err: 'NO LISTBOX' };
const label = (o) => txt(o.querySelector('span')?.innerText || o.innerText);
const opts = [...lb.querySelectorAll('[role=option]')];
const offered = opts.map(label);
const std = opts.find((o) => label(o) === 'Standard $');
if (!std) return { offered, err: 'NO STANDARD' };
(std.querySelector('button') || std).click(); await wait(900);
const standard = names();
return { dialog: 'Handle Color', totalBefore: before.length, offered, standardCount: standard.length, standard };
}
